import{_ as a,o,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"বিচ্ছিন্ন স্থান কম দূষণ প্রক্রিয়া","description":"","frontmatter":{},"headers":[],"relativePath":"bn/0086-隔离空间低污染流程.md","filePath":"bn/0086-隔离空间低污染流程.md"}'),e={name:"bn/0086-隔离空间低污染流程.md"};function l(i,t,n,h,s,u){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="বিচ্ছিন্ন-স্থান-কম-দূষণ-প্রক্রিয়া" tabindex="-1">বিচ্ছিন্ন স্থান কম দূষণ প্রক্রিয়া <a class="header-anchor" href="#বিচ্ছিন্ন-স্থান-কম-দূষণ-প্রক্রিয়া" aria-label="Permalink to &quot;বিচ্ছিন্ন স্থান কম দূষণ প্রক্রিয়া&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>86</td></tr><tr><td>মডিউল</td><td>আন্তঃ-তল মিথস্ক্রিয়া ও সময় নিয়ম</td></tr><tr><td>মূল কীওয়ার্ড</td><td>বিচ্ছিন্ন স্থান, কম দূষণ, আইনি প্রাচীর, বিশুদ্ধকরণ প্রক্রিয়া, দূষণ পর্যবেক্ষণ</td></tr></tbody></table><h2 id="_1-বিচ্ছিন্ন-স্থানের-সংজ্ঞা-ও-কার্যকারিতা" tabindex="-1">1. বিচ্ছিন্ন স্থানের সংজ্ঞা ও কার্যকারিতা <a class="header-anchor" href="#_1-বিচ্ছিন্ন-স্থানের-সংজ্ঞা-ও-কার্যকারিতা" aria-label="Permalink to &quot;1. বিচ্ছিন্ন স্থানের সংজ্ঞা ও কার্যকারিতা&quot;">​</a></h2><p>বিচ্ছিন্ন স্থান হলো স্থান আইন নিয়ন্ত্রণ প্রযুক্তির মাধ্যমে আইন নেটওয়ার্কে নির্মিত একটি স্বাধীন বদ্ধ অঞ্চল, যা প্রতিলিপি দর্পণ অন্যতল প্রত্নতত্ত্ব পরিকল্পনার মূল কর্মস্থল। বিচ্ছিন্ন স্থান ও বাহ্যিক মহাবিশ্বের মধ্যে সম্পূর্ণ আইনি প্রাচীর দ্বারা সম্পূর্ণরূপে পৃথক করা হয়, অভ্যন্তরে স্বাধীন আইনি প্যারামিটার ব্যবস্থা ও শক্তি চক্র ব্যবস্থা রয়েছে। এর মূল কার্যকারিতা হলো প্রত্নতত্ত্ব প্রতিলিপির জন্য একটি স্থিতিশীল, নিয়ন্ত্রণযোগ্য, লক্ষ্য থেকে সম্পূর্ণ বিচ্ছিন্ন গবেষণা পরিবেশ প্রদান করা, একই সাথে নিশ্চিত করা যে প্রত্নতত্ত্ব প্রক্রিয়াতে উৎপন্ন সমস্ত দূষণ কঠোরভাবে বিচ্ছিন্ন স্থানের অভ্যন্তরে সীমাবদ্ধ থাকে, নিজের তল বা লক্ষ্য তলে বাইরে বের হয় না।</p><p>বিচ্ছিন্ন স্থানের নির্মাণ স্থান আইন নিয়ন্ত্রণ ব্যবস্থার চতুর্থ স্তর (ফা-কুং জিং) এর আইনি অপারেশন ক্ষমতার উপর ভিত্তি করে। নির্মাতাকে আইন নেটওয়ার্কে একটি &quot;আইনি ফাঁক অঞ্চল&quot; নির্বাচন করতে হয় — অর্থাৎ বিদ্যমান আইনি প্যারামিটার তুলনামূলকভাবে সমান, কোনো তলের কাঠামো নেই এমন অঞ্চল, তারপর স্থান আইনি অপারেশনের মাধ্যমে该 অঞ্চলে একটি গোলাকার বা ঘনাকৃতির বদ্ধ স্থান তৈরি করা, এবং এর জন্য স্বাধীন আইনি প্যারামিটার সেট করা। বিচ্ছিন্ন স্থানের আকার চাহিদা অনুযায়ী সামঞ্জস্য করা যায়, স্বাভাবিক প্রত্নতত্ত্বের জন্য বিচ্ছিন্ন স্থানের আয়তন সাধারণত 1000 থেকে 100000 ঘনমিটারের মধ্যে থাকে।</p><p>বিচ্ছিন্ন স্থান একবারব্যবহারযোগ্য খরচবস্তু নয়, বরং পুনরায় ব্যবহারযোগ্য মৌলিক অবকাঠামো। হেংইয়ান-ঝৌ প্রধান অ্যাঙ্করগুলির কাছে মানক &quot;বিচ্ছিন্ন স্থান গোষ্ঠী&quot; প্রতিষ্ঠা করেছে, প্রত্নতত্ত্ব টিম চাহিদা অনুযায়ী ভাড়া নিতে পারে। প্রতিটি প্রত্নতত্ত্ব কাজ শেষ হওয়ার পর, বিচ্ছিন্ন স্থান সম্পূর্ণ বিশুদ্ধকরণ ও পুনঃসেট করার পর, পরের ব্যবহারে নিযুক্ত করা যায়।</p><h2 id="_2-কম-দূষণ-প্রক্রিয়ার-সামগ্রিক-কাঠামো" tabindex="-1">2. কম দূষণ প্রক্রিয়ার সামগ্রিক কাঠামো <a class="header-anchor" href="#_2-কম-দূষণ-প্রক্রিয়ার-সামগ্রিক-কাঠামো" aria-label="Permalink to &quot;2. কম দূষণ প্রক্রিয়ার সামগ্রিক কাঠামো&quot;">​</a></h2><p>বিচ্ছিন্ন স্থান কম দূষণ প্রক্রিয়া হলো প্রত্নতত্ত্বের সম্পূর্ণ প্রক্রিয়া জুড়ে একটি দূষণ প্রতিরোধ ব্যবস্থা, যার সামগ্রিক কাঠামো &quot;আগে প্রতিরোধ, মাঝে পর্যবেক্ষণ, পরে বিশুদ্ধকরণ&quot; তিনটি পর্যায়ে বিভক্ত, প্রতিটি পর্যায়ে স্পষ্ট অপারেশন নিয়ম ও মানের মানদণ্ড রয়েছে। কম দূষণ প্রক্রিয়ার লক্ষ্য হলো প্রত্নতত্ত্ব অপারেশনের বাহ্যিক পরিবেশ (নিজের তল ও লক্ষ্য তল সহ) উপর দূষণের প্রভাবকে &quot;আইনি উপেক্ষা যোগ্য স্তর&quot; এ নামিয়ে আনা — অর্থাৎ দূষণের পরিমাণ আইন নেটওয়ার্কের প্রাকৃতিক ওঠানামার পরিমাণের চেয়ে কম থাকে, কোনো তলের আইনি পর্যবেক্ষণ ব্যবস্থা দ্বারা উপলব্ধি করা যায় না।</p><h3 id="_2-1-আগে-প্রতিরোধ-পর্যায়" tabindex="-1">2.1 আগে প্রতিরোধ পর্যায় <a class="header-anchor" href="#_2-1-আগে-প্রতিরোধ-পর্যায়" aria-label="Permalink to &quot;2.1 আগে প্রতিরোধ পর্যায়&quot;">​</a></h3><p>আগে প্রতিরোধ প্রত্নতত্ত্ব কাজ আনুষ্ঠানিকভাবে শুরু হওয়ার আগে সম্পাদিত হয়, মূলত নিম্নলিখিত কাজ অন্তর্ভুক্ত:</p><ol><li><p><strong>বিচ্ছিন্ন স্থান নির্বাচন ও কাস্টমাইজেশন</strong>: প্রত্নতত্ত্ব লক্ষ্যের আইনি বৈশিষ্ট্য অনুযায়ী, সংশ্লিষ্ট আইনি প্যারামিটার সহ বিচ্ছিন্ন স্থান নির্বাচন বা কাস্টমাইজ করা। বিচ্ছিন্ন স্থানের অভ্যন্তরে আইনি প্যারামিটার যতটা সম্ভব লক্ষ্য তলের পরিবেশ প্যারামিটারের কাছাকাছি হওয়া উচিত, যাতে প্রতিলিপির স্থিতিশীলতা নিশ্চিত হয়, একই সাথে নিজের তলের আইনি প্যারামিটারের সাথে যথেষ্ট পার্থক্য বজায় রাখা উচিত, যাতে প্রতিলিপি পদার্থ ও নিজের তলের আইনের মধ্যে প্রতিকূল প্রতিক্রিয়া না ঘটে।</p></li><li><p><strong>প্রাচীরের শক্তি পরীক্ষা</strong>: বিচ্ছিন্ন স্থানের আইনি প্রাচীরের সম্পূর্ণ পরীক্ষা করা, নিশ্চিত করা যে প্রাচীরের অখণ্ডতা ও শক্তি মানদণ্ডে পৌঁছেছে। প্রাচীরের শক্তি &quot;আইনি অনুপ্রবেশ গুণাঙ্ক&quot; দ্বারা মাপা হয়, মানদণ্ডের দাবি হলো অনুপ্রবেশ গুণাঙ্ক 10 এর ঋণাত্মক 15 ঘাতের নিচে — অর্থাৎ প্রতি সেকেন্ডে প্রাচীর দিয়ে যাওয়া আইনি তথ্যের পরিমাণ 10 এর ঋণাত্মক 15 ঘাত বিটের বেশি নয়। পরীক্ষায় অযোগ্য বিচ্ছিন্ন স্থান ব্যবহারে নিযুক্ত করা যাবে না।</p></li><li><p><strong>কর্মী বিশুদ্ধকরণ</strong>: বিচ্ছিন্ন স্থানে প্রবেশকারী সমস্ত প্রত্নতত্ত্ব কর্মীকে প্রবেশের আগে &quot;ত্রিস্তর বিশুদ্ধকরণ প্রক্রিয়া&quot; (জৈব বিশুদ্ধকরণ, শক্তি বিশুদ্ধকরণ, চেতনা বিশুদ্ধকরণ) সম্পন্ন করতে হবে, বিস্তারিত দেখুন নথি 81 &quot;তল অতিক্রম নিয়ম&quot;। বিশুদ্ধকরণ সম্পন্ন হওয়ার পর, কর্মীদের মানক &quot;আইনি বিচ্ছিন্ন পোশাক&quot; পরতে হবে, এই পোশাকটি কর্মীর শরীরের ভেতরের শক্তি ও চেতনার ওঠানামা বাইরে যাওয়াকে আরও বাধা দিতে সক্ষম।</p></li><li><p><strong>ডিভাইস বিশুদ্ধকরণ</strong>: বিচ্ছিন্ন স্থানে নিয়ে যাওয়া সমস্ত ডিভাইস ও সরঞ্জামও বিশুদ্ধকরণ প্রক্রিয়ার মধ্য দিয়ে যেতে হবে, নিশ্চিত করা যে ডিভাইসের পৃষ্ঠে ও অভ্যন্তরে নিজের তলের অণুজীব, শক্তির অবশিষ্টাংশ ও তথ্যের টুকরো বহন করে না। ডিভাইস বিশুদ্ধকরণ &quot;আইনি স্ক্যান অপসারণ পদ্ধতি&quot; ব্যবহার করে, উচ্চ-ফ্রিকোয়েন্সি আইনি স্ক্যানের মাধ্যমে ডিভাইসের সব বহিরাগত অবশিষ্টাংশকে আলাদা করে।</p></li></ol><h3 id="_2-2-মাঝে-পর্যবেক্ষণ-পর্যায়" tabindex="-1">2.2 মাঝে পর্যবেক্ষণ পর্যায় <a class="header-anchor" href="#_2-2-মাঝে-পর্যবেক্ষণ-পর্যায়" aria-label="Permalink to &quot;2.2 মাঝে পর্যবেক্ষণ পর্যায়&quot;">​</a></h3><p>প্রত্নতত্ত্ব অপারেশন চলাকালীন, কম দূষণ প্রক্রিয়ার মূল ফোকাস হলো রিয়েল-টাইম পর্যবেক্ষণ ও তাৎক্ষণিক প্রতিক্রিয়া। বিচ্ছিন্ন স্থানের অভ্যন্তরে সর্বত্র দূষণ পর্যবেক্ষণ ব্যবস্থা স্থাপন করা হয়েছে, যার মধ্যে অন্তর্ভুক্ত:</p><table tabindex="0"><thead><tr><th>পর্যবেক্ষণের ধরন</th><th>পর্যবেক্ষণের বিষয়বস্তু</th><th>অ্যালার্মের সীমা</th><th>প্রতিক্রিয়ার ব্যবস্থা</th></tr></thead><tbody><tr><td>জৈব দূষণ পর্যবেক্ষণ</td><td>বিচ্ছিন্ন স্থানে প্রতিলিপি উৎস ছাড়া অন্য কোনো অণুজীব উপস্থিত আছে কিনা</td><td>1টি বহিরাগত অণুজীব আবিষ্কৃত</td><td>অবিলম্বে স্থানীয় জীবাণুনাশক শুরু করা, কর্মী বিশুদ্ধকরণ রেকর্ড পরীক্ষা করা</td></tr><tr><td>শক্তি দূষণ পর্যবেক্ষণ</td><td>বিচ্ছিন্ন স্থানের শক্তি ক্ষেত্রে অস্বাভাবিক ওঠানামা দেখা দিচ্ছে কিনা</td><td>ওঠানামার পরিমাণ বেসলাইন মানের 0.01% অতিক্রম করে</td><td>প্রত্নতত্ত্ব অপারেশন স্থগিত করা, ওঠানামার উৎস সনাক্ত করে নির্মূল করা</td></tr><tr><td>চেতনা দূষণ পর্যবেক্ষণ</td><td>বিচ্ছিন্ন স্থানের চেতনা অঞ্চলে বহিরাগত চেতনা সংকেত দেখা দিচ্ছে কিনা</td><td>সংকেতের শক্তি 10 এর ঋণাত্মক 8 ঘাত চেতনা একক অতিক্রম করে</td><td>চেতনা বাধা ক্ষেত্র শুরু করা, কর্মীর চেতনার অবস্থা পরীক্ষা করা</td></tr><tr><td>প্রাচীর অখণ্ডতা পর্যবেক্ষণ</td><td>আইনি প্রাচীরে ফাটল বা দুর্বল বিন্দু দেখা দিয়েছে কিনা</td><td>অনুপ্রবেশ গুণাঙ্ক 10 এর ঋণাত্মক 12 ঘাত অতিক্রম করে</td><td>অবিলম্বে প্রাচীর মেরামত প্রক্রিয়া শুরু করা, প্রয়োজনে জরুরি প্রত্যাহার</td></tr></tbody></table><p>পর্যবেক্ষণ ব্যবস্থা স্বাধীন &quot;দূষণ তত্ত্বাবধানকারী&quot; দ্বারা দায়িত্বশীলভাবে পরিচালিত হয়, তত্ত্বাবধানকারী নির্দিষ্ট প্রত্নতত্ত্ব অপারেশনে অংশগ্রহণ করেন না, বিশেষভাবে দূষণ পর্যবেক্ষণ ও জরুরি প্রতিক্রিয়ার জন্য দায়ী। একবার দূষণ সীমা অতিক্রম করা আবিষ্কৃত হলে, তত্ত্বাবধানকারীর সমস্ত প্রত্নতত্ত্ব অপারেশন অবিলম্বে স্থগিত করার এবং সংশ্লিষ্ট জরুরি প্রক্রিয়া শুরু করার অধিকার রয়েছে।</p><h3 id="_2-3-পরে-বিশুদ্ধকরণ-পর্যায়" tabindex="-1">2.3 পরে বিশুদ্ধকরণ পর্যায় <a class="header-anchor" href="#_2-3-পরে-বিশুদ্ধকরণ-পর্যায়" aria-label="Permalink to &quot;2.3 পরে বিশুদ্ধকরণ পর্যায়&quot;">​</a></h3><p>প্রত্নতত্ত্ব কাজ শেষ হওয়ার পর, অবশ্যই বিচ্ছিন্ন স্থানের সম্পূর্ণ বিশুদ্ধকরণ ও পুনঃসেট করতে হবে, নিশ্চিত করা যে বিচ্ছিন্ন স্থানে কোনো প্রতিলিপি পদার্থ, শক্তির অবশিষ্টাংশ বা তথ্যের টুকরো অবশিষ্ট নেই। পরে বিশুদ্ধকরণ চারটি ধাপে বিভক্ত:</p><ol><li><p><strong>প্রতিলিপি ধ্বংস</strong>: বিচ্ছিন্ন স্থানের সমস্ত প্রতিলিপি পদার্থকে &quot;আইনি বিনাশ প্রক্রিয়া&quot;র মাধ্যমে সম্পূর্ণরূপে ধ্বংস করা। আইনি বিনাশ প্রক্রিয়া প্রতিলিপি পদার্থের কণা কাঠামোকে সম্পূর্ণরূপে ভেঙে মৌলিক শক্তিতে রূপান্তর করে, তারপর শক্তিকে বিচ্ছিন্ন স্থানের শক্তি চক্র ব্যবস্থায় নিয়ে যাওয়া হয় নিরপেক্ষকরণের জন্য। ধ্বংস প্রক্রিয়াতে অবশ্যই নিশ্চিত করতে হবে যে পদার্থের বিনাশের হার 100% এ পৌঁছেছে, কোনো কণার অবশিষ্টাংশ থাকতে দেওয়া যাবে না।</p></li><li><p><strong>শক্তি নিরপেক্ষকরণ</strong>: বিচ্ছিন্ন স্থানের শক্তি ক্ষেত্রের সম্পূর্ণ নিরপেক্ষকরণ করা, প্রত্নতত্ত্ব প্রক্রিয়াতে উৎপন্ন সমস্ত অস্বাভাবিক শক্তি ওঠানামা নির্মূল করা, শক্তি ক্ষেত্রকে বিচ্ছিন্ন স্থানের বেসলাইন অবস্থায় ফিরিয়ে আনা। শক্তি নিরপেক্ষকরণ &quot;বিপরীত তরঙ্গ প্রতিরোধ পদ্ধতি&quot; ব্যবহার করে, অস্বাভাবিক ওঠানামার ফেজের বিপরীত শক্তি তরঙ্গ তৈরি করার মাধ্যমে সুনির্দিষ্ট প্রতিরোধ অর্জন করে।</p></li><li><p><strong>তথ্য অপসারণ</strong>: বিচ্ছিন্ন স্থানের চেতনা অঞ্চল ও তথ্য স্তরের গভীর অপসারণ করা, প্রত্নতত্ত্ব প্রক্রিয়াতে উৎপন্ন সমস্ত তথ্য অবশিষ্টাংশ নির্মূল করা। তথ্য অপসারণ &quot;আইনি পুনর্লিখন পদ্ধতি&quot; ব্যবহার করে, এলোমেলো শব্দ তথ্য দিয়ে মূল তথ্য অবশিষ্টাংশকে কভার করে, তারপর আবার শব্দ তথ্য অপসারণ করে, নিশ্চিত করা যে অপসারিত তথ্য কোনো প্রযুক্তিগত উপায়ে ফিরিয়ে আনা যাবে না।</p></li><li><p><strong>স্থান পুনঃসেট</strong>: উপরের তিনটি ধাপ সম্পন্ন হওয়ার পর, বিচ্ছিন্ন স্থানের সামগ্রিক আইনি পুনঃসেট করা, অভ্যন্তরীণ আইনি প্যারামিটারকে ফ্যাক্টরি মানক অবস্থায় ফিরিয়ে আনা। পুনঃসেটের পর, বিচ্ছিন্ন স্থান নতুন এক রাউন্ডের প্রাচীর পরীক্ষা ও দূষণ পরীক্ষা দিয়ে গেছে, যোগ্যতা নিশ্চিত হওয়ার পর সংরক্ষণে রাখা যায়।</p></li></ol><h2 id="_3-দূষণ-দুর্ঘটনার-শ্রেণীবিভাগ-ও-নিষ্পত্তি" tabindex="-1">3. দূষণ দুর্ঘটনার শ্রেণীবিভাগ ও নিষ্পত্তি <a class="header-anchor" href="#_3-দূষণ-দুর্ঘটনার-শ্রেণীবিভাগ-ও-নিষ্পত্তি" aria-label="Permalink to &quot;3. দূষণ দুর্ঘটনার শ্রেণীবিভাগ ও নিষ্পত্তি&quot;">​</a></h2><p>কঠোর কম দূষণ প্রক্রিয়া থাকা সত্ত্বেও, দূষণ দুর্ঘটনার সম্ভাবনা সম্পূর্ণরূপে বাদ দেওয়া যায় না। হেংইয়ান-ঝৌ বিচ্ছিন্ন স্থান দূষণ দুর্ঘটনাকে তিনটি শ্রেণীতে বিভক্ত করেছে:</p><ul><li><p><strong>প্রথম শ্রেণীর দুর্ঘটনা (সামান্য দূষণ)</strong>: অল্প পরিমাণ দূষণকারী পদার্থ বা শক্তি বিচ্ছিন্ন স্থানের অভ্যন্তরে সীমাবদ্ধ, আইনি প্রাচীর ভাঙেনি। নিষ্পত্তির পদ্ধতি: বিচ্ছিন্ন স্থানে স্থানীয় বিশুদ্ধকরণ করা, বাহ্যিক পরিবেশকে প্রভাবিত করে না, পরে দুর্ঘটনা রিপোর্ট জমা দিলেই হয়।</p></li><li><p><strong>দ্বিতীয় শ্রেণীর দুর্ঘটনা (প্রাচীর ভাঙা)</strong>: দূষণ আইনি প্রাচীর ভেঙেছে, কিন্তু দূষণের পরিমাণ কম এবং সময়মতো আবিষ্কৃত হয়েছে, নিজের তলের আইন নেটওয়ার্কে ছড়িয়ে পড়েনি। নিষ্পত্তির পদ্ধতি: অবিলম্বে প্রাচীর মেরামত ও বাহ্যিক বিশুদ্ধকরণ প্রক্রিয়া শুরু করা, দূষণ তত্ত্বাবধানকারীকে অবশ্যই তল ব্যবস্থাপনা ব্যুরোতে বিস্তারিত দুর্ঘটনা রিপোর্ট জমা দিতে হবে, সংশ্লিষ্ট ব্যক্তিরা তদন্তের শিকার হন।</p></li><li><p><strong>তৃতীয় শ্রেণীর দুর্ঘটনা (গুরুতর বিস্তার)</strong>: দূষণ ব্যাপকভাবে নিজের তলের আইন নেটওয়ার্কে ছড়িয়ে পড়েছে, নিজের তলের আইনি স্থিতিশীলতা বা পরিবেশগত পরিস্থিতিকে প্রভাবিত করতে পারে। নিষ্পত্তির পদ্ধতি: অবিলম্বে সর্বোচ্চ স্তরের জরুরি প্রতিক্রিয়া শুরু করা, অ্যাঙ্কর কাউন্সিল সরাসরি দূষণ অপসারণ ও কার্য-কারণ মেরামতের কাজ নির্দেশ করে, সংশ্লিষ্ট দায়ী ব্যক্তিরা আইনি শাস্তির মুখোমুখি হবেন।</p></li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>বিচ্ছিন্ন স্থান কম দূষণ প্রক্রিয়া হলো &quot;প্রতিরোধ প্রধান, পর্যবেক্ষণ সহায়ক, বিশুদ্ধকরণ চূড়ান্ত&quot; এর একটি সম্পূর্ণ দূষণ প্রতিরোধ ব্যবস্থা। এটি আগের কঠোর প্রতিরোধ, মাঝের রিয়েল-টাইম পর্যবেক্ষণ ও পরের সম্পূর্ণ বিশুদ্ধকরণের মাধ্যমে, প্রত্নতত্ত্ব অপারেশনের দূষণের ঝুঁকিকে সর্বনিম্নে নামিয়ে আনে। এই প্রক্রিয়াটি অ্যাঙ্কর সিম্বায়োসিস সভ্যতার মহাবিশ্বের পরিবেশের প্রতি দায়িত্ববোধকে প্রকাশ করে — এমনকি জ্ঞানের সন্ধানের প্রক্রিয়াতেও, অন্য স্থানকে দূষিত করার মূল্যে কখনো কাজ করে না।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>84-প্রত্নতত্ত্ব চুক্তি মূল নীতি</li><li>85-প্রতিলিপি দর্পণ অন্যতল প্রত্নতত্ত্ব পরিকল্পনা</li><li>64-বিচ্ছিন্ন স্থান নির্মাণ প্রযুক্তি</li></ul>',25)])])}const _=a(e,[["render",l]]);export{q as __pageData,_ as default};
